    out = [[7] * w for _ in range(h)]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 7 or (r, c) in seen:
                continue
            cells, stack = [], [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if not (dy or dx):
                            continue
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny, nx) not in seen:
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            best = None
            for radius in range(max(h, w) + 1):
                for cy in range(-radius, h + radius):
                    for cx in range(-radius, w + radius):
                        if all(abs(y - cy) + abs(x - cx) == radius for y, x in cells):
                            best = (cy, cx, radius)
                            break
                    if best:
                        break
                if best:
                    break
            if best is None:
                for y, x in cells:
                    out[y][x] = color
                continue
            cy, cx, radius = best
            if color == 2:
                radius = max(0, radius - 1)
            elif color == 5:
                radius += 1
            if radius == 0:
                if 0 <= cy < h and 0 <= cx < w:
                    out[cy][cx] = color
            else:
                for dy in range(-radius, radius + 1):
                    dx = radius - abs(dy)
                    for x in ({cx - dx, cx + dx} if dx else {cx}):
                        y = cy + dy
                        if 0 <= y < h and 0 <= x < w:
                            out[y][x] = color
    return out
